def page(path,name,body,desc='Explore Waterloo Bike Shop: bicycles, parts, accessories and expert service.'):
 file=D/(path.strip('/')+'/index.html' if path.endswith('/') else path.strip('/'));file.parent.mkdir(parents=True,exist_ok=True);file.write_text(f'<!doctype html><html lang="en"><head>{head}<title>{e(name)} | Waterloo Bike Shop</title><meta name="description" content="{e(desc)}"></head><body class="inner-page"><a class="skip" href="#page-content">Skip to content</a>{header}<main id="page-content">{body}</main>{footer}</body></html>');paths.append(path)
def intro(kicker,h1,copy,back='Shop',parent='/bicycles/'):
 return f'<section class="page-intro"><div class="crumb"><a href="/">Home</a><span>/</span><a href="{parent}">{e(back)}</a></div><div class="intro-line"><div><span class="eyebrow">{e(kicker)}</span><h1>{h1}</h1></div><p>{copy}</p></div></section>'
def card(p):
 price=f'C${p["price"]:,.2f}' if p['price'] is not None else 'View options'
