def tiles(items):
 return '<div class="category-grid">'+''.join(f'<a class="category-tile" href="{c["path"]}"><div class="category-picture">'+(f'<img src="{c["image"]}" alt="{e(title(c["title"]))}" loading="lazy">' if c.get('image')else'<span class="category-monogram" aria-hidden="true">'+e(title(c['title'])[:1])+'</span>')+f'</div><h3>{e(title(c["title"]))}<span>↗</span></h3></a>'for c in items)+'</div>'
