rootcopy={'bicycles':('Find your<br><em>kind of freedom.</em>','From the everyday commute to your next dirt-road detour. Start with the way you want to ride.'),'accessories':('The little things.<br><em>The big difference.</em>','Carry more. See further. Feel ready. Find the finishing touches for the way you ride.'),'components':('Make a good bike<br><em>feel like yours.</em>','Wheels, tyres, brakes and the parts in between. Start with the right fit, then dial in the details.'),'tools-lubricants':('A little care.<br><em>A lot more miles.</em>','The right tools, cleaners and lubricants help keep your favourite bike ready for its next ride.')}
for path,c in cats.items():
 name=title(c['title']);children=[v for v in cats.values()if v['parent']==path and v['path']!=path];root=path.strip('/').split('/')[0];isroot=path=='/'+root+'/'
 h,copy=rootcopy.get(root,('Find your ride.','Explore the selection.'))if isroot else (e(name)+'.<br><em>Go your own way.</em>','Find the right '+e(name.lower())+' for your next ride. Need help with sizing or compatibility? Ask the shop before you choose.')
