page('/service-repair/','The workshop',intro('GOOD PEOPLE. PRECISE WORK.','Back to your<br><em>best ride.</em>','Family-run service, experienced hands and an explanation of what your bike needs—and why.',parent='/',back='Home')+'<section class="service-lead"><div><h2>Less guesswork.<br>More good miles.</h2><p>Start with a tune-up package or arrange a visit. The team will assess the right service when your bicycle is dropped off or collected.</p><a class="button dark" href="/service-repair/service-booking/">Book your bike in ↗</a></div><img src="/assets/ride.jpg" alt="A close view of a bicycle saddle and frame" loading="lazy"></section><section class="packages-section"><div class="catalog-title"><h2>Care, at every level.</h2><a class="text-link" href="/service-repair/tune-up-packages/">Compare the packages ↗</a></div>'+packagecards()+'</section>')
page('/service-repair/tune-up-packages/','Tune-up packages',intro('CARE THAT GOES FURTHER','Give your bike<br><em>its good feeling back.</em>','Three levels of care, from essential adjustments to a comprehensive overhaul.',parent='/service-repair/',back='Workshop')+'<section class="packages-section">'+packagecards()+'<p class="catalog-note">Service pricing listed by the shop. Confirm the final work and cost with the team. Typical turnaround is 3–5 days.</p></section><section class="faq-section"><h2>A few useful details.</h2><details><summary>What if I’m not sure which service to choose?</summary><p>Choose the package that seems closest to your needs. The shop will assess the appropriate work when your bike arrives.</p></details><details><summary>Are new parts included in the price?</summary><p>Parts are separate. Annual and Deluxe include labour for new-part installation; Essential does not.</p></details><details><summary>What about suspension and hydraulic brakes?</summary><p>Shock, fork and dropper rebuilds, and disc-brake bleeding, are outside the listed package inclusions. Ask the team for a quote.</p></details></section>')
